using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — the SDK resolves IHttpClientFactory and ILogger
/// from DI automatically; they never appear in the tool schema sent to LLMs.
/// </summary>
[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOpts = new() { WriteIndented = true };

    [McpServerTool, Description("Get a post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{id}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var json = await client.GetStringAsync(url, cancellationToken);

        // Return a compact summary so the LLM isn't overwhelmed.
        var posts = JsonSerializer.Deserialize<JsonElement>(json);
        return $"Found {posts.GetArrayLength()} posts.\n{json}";
    }

    [McpServerTool, Description("Create a new post.")]
    public async Task<string> CreatePost(
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var client = httpFactory.CreateClient("api");

        var payload = JsonSerializer.Serialize(new { title, body, userId });
        var content = new StringContent(payload, Encoding.UTF8, "application/json");

        var response = await client.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Get all comments for a given post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var json = await client.GetStringAsync($"/posts/{postId}/comments", cancellationToken);
        return json;
    }
}

